const response = $input.first().json || {};
const base = $('Подготовить конфиг синхронизации').first().json || {};
const rows = Array.isArray(response.data) ? response.data : [];
return [{ json: { ...base, masters_count: rows.length, is_noop: rows.length === 0, rows } }];

function cleanText(value) {
  const result = String(value ?? '').trim();
  return result || null;
}

function cleanInteger(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : fallback;
}

function cleanNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function cleanDate(value) {
  const result = cleanText(value);
  if (!result) return null;
  const date = new Date(result);
  return Number.isNaN(date.getTime()) ? null : date.toISOString().slice(0, 10);
}

function cleanBoolean(value) {
  if (typeof value === 'boolean') return value;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed === 1 : false;
}

const shared = $('Собрать список мастеров').first().json || $('Подготовить конфиг синхронизации').first().json || {};
const sourceRows = Array.isArray($input.first().json.rows) ? $input.first().json.rows : [];

return sourceRows
  .map((row) => {
    const ycId = Number(row?.id || 0);
    const name = cleanText(row?.name);
    if (!Number.isFinite(ycId) || ycId <= 0 || !name) return null;

    return {
      json: {
        org_uid: shared.org_uid,
        yc_id: ycId,
        company_id: Number(shared.company_id),
        name,
        specialization: cleanText(row?.specialization),
        bookable: cleanBoolean(row?.bookable),
        fired: cleanBoolean(row?.fired),
        hidden: cleanBoolean(row?.hidden),
        status: cleanInteger(row?.status, 0),
        user_id: row?.user_id == null ? null : cleanInteger(row.user_id, 0),
        api_id: cleanText(row?.api_id),
        avatar: cleanText(row?.avatar),
        avatar_big: cleanText(row?.avatar_big),
        information: cleanText(row?.information),
        position: Array.isArray(row?.position) ? row.position : [],
        position_id: cleanInteger(row?.position_id, 0),
        prepaid: cleanText(row?.prepaid),
        rating: cleanNumber(row?.rating, 0),
        show_rating: cleanBoolean(row?.show_rating),
        votes_count: cleanInteger(row?.votes_count, 0),
        comments_count: cleanInteger(row?.comments_count, 0),
        schedule_till: cleanDate(row?.schedule_till),
        weight: cleanInteger(row?.weight, 0),
        image_group: Array.isArray(row?.image_group) ? row.image_group : [],
        raw_payload: row
      }
    };
  })
  .filter(Boolean);

const rows = $input.all().map((item) => item.json).filter(Boolean);
const shared = $('Собрать список мастеров').first().json || $('Подготовить конфиг синхронизации').first().json || {};
return [{ json: { ...shared, synced_masters: rows.length, rows } }];

const batch = $('Собрать upsert batch').first().json || {};
const response = $input.first().json;
const insertedOrUpdated = Array.isArray(response) ? response.length : (response ? 1 : 0);
return [{ json: { ok: true, status: 'success', data: { org_uid: batch.org_uid, workflow_name: batch.workflow_name, total_masters: batch.masters_count || 0, synced_masters: batch.synced_masters || 0, inserted_or_updated: insertedOrUpdated, company_id: batch.company_id, sync_started_at: batch.sync_started_at, sync_finished_at: new Date().toISOString() }, errors: [] } }];
